# -*- coding: utf-8 -*-
"""Простые объяснения для оператора. Ключ — заголовок проверенного разбора (t из kb_verified*).
Значение: (короткий заголовок, что случилось — одна-две фразы простыми словами, [1–3 действия]).
Технические подробности остаются в kb_verified и показываются в свёрнутом блоке."""

SIMPLE = {}
NOFLY = "Не взлетай."
TECH = "Передай настройщику дрона"
WAIT = "Подожди 1–2 минуты и попробуй снова."
OUT = "Выйди на открытое место (без деревьев и зданий рядом) и подожди 2–5 минут."
REB = "Выключи питание дрона полностью и включи снова."


def S(t, title, what, steps):
    SIMPLE[t] = (title, what, list(steps))


def CFG(t, title, what, param):
    S(t, title, what + " Это ошибка настройки, оператор сам её не исправит.", [NOFLY, TECH + ": " + param + "."])


def HW(t, title, what):
    S(t, title, what, [REB, "Если повторяется — " + NOFLY.lower() + " " + TECH + ": возможна неисправность."])


def INFO(t, title, what):
    S(t, title, what, ["Ничего делать не нужно."])


